### 9. ProductAssembleService에서의 캐시 사용 패턴

**파일**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/ProductAssembleService.kt`

```kotlin
@Service
class ProductAssembleService(
    private val cachedProxyApplicationService: CachedProxyApplicationService,
) {
    fun assemble(documents: List<ChangedData<Product>>): List<IndexDocument<ProductDocument>> {
        val dependencyId = getDependencyId(documents)
        val dependency = cachedProxyApplicationService.fetchDependencies(dependencyId)

        return documents.map {
            if (it.op == Operation.CREATE) {
                require(it.afterData != null) { ... }
                require(dependency.categories[it.afterData!!.categoryId] != null) { ... }
            }

            it.toIndexDocument(
                category = dependency.categories[it.afterData?.categoryId],
                mall = dependency.malls[it.afterData?.mallId],
                brandProjection = dependency.brands[it.afterData?.brandId],
                manufacturerProjection = dependency.manufacturers[it.afterData?.manufacturerId],
            )
        }
    }

    fun getDependencyId(documents: List<ChangedData<Product>>): DependencyId {
        // 문서들에서 필요한 의존성 ID들을 추출
        val categoryIds: MutableList<Int> = mutableListOf()
        val mallIds: MutableList<Int> = mutableListOf()
        // ... 기타 ID 추출

        return DependencyId(
            categoryIds = categoryIds.distinct(),
            mallIds = mallIds.distinct(),
            // ...
        )
    }
}
```

#### 9.1 CachedProxyApplicationService

**파일**: `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/proxy/CachedProxyApplicationService.kt`

```kotlin
@Service
class CachedProxyApplicationService(
    private val categoryApplicationService: CategoryApplicationService,
    private val brandApplicationService: BrandApplicationService,
    private val manufacturerApplicationService: ManufacturerApplicationService,
    private val mallApplicationService: MallApplicationService,
) {
    fun fetchDependencies(dependencyId: DependencyId): Dependency =
        runBlocking(Dispatchers.IO) {
            val categoriesDeferred = async {
                if (dependencyId.categoryIds.isEmpty()) {
                    emptyMap()
                } else {
                    categoryApplicationService.getCachedAllByIds(dependencyId.categoryIds)
                }
            }

            val mallsDeferred = async {
                if (dependencyId.mallIds.isEmpty()) {
                    emptyMap()
                } else {
                    mallApplicationService.getCachedAllByIds(dependencyId.mallIds)
                }
            }

            Dependency(
                categories = categoriesDeferred.await(),
                malls = mallsDeferred.await(),
                // ...
            )
        }
}
```

**패턴:**
- 병렬 처리를 위해 coroutine의 `async/await` 사용
- `getCachedAllByIds()` 메서드를 통해 계층적 캐시에서 데이터 조회
- 여러 서비스의 데이터를 병렬로 조회하여 성능 최적화

